import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>
#include <float.h>
#define D 1024
#define BLOCK_N 64
#define D_TILE 128
#define WARPS_PER_BLOCK 8
#define D_PER_THREAD (D/32)
__device__ __forceinline__ void issue_load_tile(
    const half* __restrict__ base, int n0, int n_count, int d0,
    half sTile[2][BLOCK_N][D_TILE], int buf, int tid, int block_threads)
{
    for (int idx = tid; idx < n_count * (D_TILE / 8); idx += block_threads) {
        int jj = idx / (D_TILE / 8);
        int dd8 = idx % (D_TILE / 8);
        const float4* src = reinterpret_cast<const float4*>(base + (size_t)(n0 + jj) * D + d0) + dd8;
        float4* dst = reinterpret_cast<float4*>(&sTile[buf][jj][0]) + dd8;
        unsigned dst_addr = static_cast<unsigned>(__cvta_generic_to_shared(dst));
        unsigned long long src_addr = __cvta_generic_to_global(src);
        asm volatile("cp.async.ca.shared.global [%0], [%1], 16;\n" :: "r"(dst_addr), "l"(src_addr));
    }
    asm volatile("cp.async.commit_group;\n");
}
__global__ void flash_attention_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ O,
    int B, int H, int S, float scale)
{
    constexpr int NUM_STAGES = D / D_TILE;
    constexpr int SUB = D_TILE / 32;
    int bh = blockIdx.x;
    int b = bh / H;
    int h = bh % H;
    int tid = threadIdx.x;
    int warp_id = tid / 32;
    int lane = tid % 32;
    int row = blockIdx.y * WARPS_PER_BLOCK + warp_id;
    const size_t bh_off = (size_t)(b * H + h) * (size_t)S * (size_t)D;
    const half* Kbase = K + bh_off;
    const half* Vbase = V + bh_off;
    __shared__ half sTile[2][BLOCK_N][D_TILE];
    int local_off = lane * 2;
    half2 q_reg[NUM_STAGES][SUB / 2];
    float acc[NUM_STAGES][SUB];
    if (row < S) {
        const half* Qrow = Q + bh_off + (size_t)row * D;
        #pragma unroll
        for (int s = 0; s < NUM_STAGES; s++) {
            q_reg[s][0] = *reinterpret_cast<const half2*>(Qrow + s * D_TILE + local_off);
            q_reg[s][1] = *reinterpret_cast<const half2*>(Qrow + s * D_TILE + local_off + 64);
            #pragma unroll
            for (int dd = 0; dd < SUB; dd++) acc[s][dd] = 0.0f;
        }
    }
    float m_i = -FLT_MAX;
    float l_i = 0.0f;
    for (int n0 = 0; n0 < S; n0 += BLOCK_N) {
        int n_count = min(BLOCK_N, S - n0);
        float scores[BLOCK_N];
        #pragma unroll
        for (int j = 0; j < BLOCK_N; j++) scores[j] = 0.0f;
        // ---- Phase 1: pipelined (double-buffered) full-warp Q @ K^T ----
        issue_load_tile(Kbase, n0, n_count, 0, sTile, 0, tid, blockDim.x);
        for (int stage = 0; stage < NUM_STAGES; stage++) {
            int cur = stage & 1;
            int nxt = cur ^ 1;
            if (stage + 1 < NUM_STAGES) {
                issue_load_tile(Kbase, n0, n_count, (stage + 1) * D_TILE, sTile, nxt, tid, blockDim.x);
                asm volatile("cp.async.wait_group 1;\n");
            } else {
                asm volatile("cp.async.wait_group 0;\n");
            }
            __syncthreads();
            if (row < S) {
                for (int j = 0; j < n_count; j++) {
                    float partial = 0.0f;
                    half2 kv0 = *reinterpret_cast<const half2*>(&sTile[cur][j][local_off]);
                    half2 kv1 = *reinterpret_cast<const half2*>(&sTile[cur][j][local_off + 64]);
                    partial += __half2float(q_reg[stage][0].x) * __half2float(kv0.x)
                             + __half2float(q_reg[stage][0].y) * __half2float(kv0.y)
                             + __half2float(q_reg[stage][1].x) * __half2float(kv1.x)
                             + __half2float(q_reg[stage][1].y) * __half2float(kv1.y);
                    #pragma unroll
                    for (int offset = 16; offset > 0; offset >>= 1) {
                        partial += __shfl_xor_sync(0xffffffff, partial, offset);
                    }
                    scores[j] += partial;
                }
            }
            __syncthreads();
        }
        float p[BLOCK_N];
        if (row < S) {
            float m_new = m_i;
            for (int j = 0; j < n_count; j++) {
                scores[j] *= scale;
                if (scores[j] > m_new) m_new = scores[j];
            }
            float alpha = expf(m_i - m_new);
            l_i *= alpha;
            #pragma unroll
            for (int s = 0; s < NUM_STAGES; s++) {
                #pragma unroll
                for (int dd = 0; dd < SUB; dd++) acc[s][dd] *= alpha;
            }
            for (int j = 0; j < n_count; j++) {
                p[j] = expf(scores[j] - m_new);
                l_i += p[j];
            }
            m_i = m_new;
        }
        // ---- Phase 2: pipelined (double-buffered) full-warp P @ V ----
        issue_load_tile(Vbase, n0, n_count, 0, sTile, 0, tid, blockDim.x);
        for (int stage = 0; stage < NUM_STAGES; stage++) {
            int cur = stage & 1;
            int nxt = cur ^ 1;
            if (stage + 1 < NUM_STAGES) {
                issue_load_tile(Vbase, n0, n_count, (stage + 1) * D_TILE, sTile, nxt, tid, blockDim.x);
                asm volatile("cp.async.wait_group 1;\n");
            } else {
                asm volatile("cp.async.wait_group 0;\n");
            }
            __syncthreads();
            if (row < S) {
                for (int j = 0; j < n_count; j++) {
                    float pj = p[j];
                    acc[stage][0] += pj * __half2float(sTile[cur][j][local_off]);
                    acc[stage][1] += pj * __half2float(sTile[cur][j][local_off + 1]);
                    acc[stage][2] += pj * __half2float(sTile[cur][j][local_off + 64]);
                    acc[stage][3] += pj * __half2float(sTile[cur][j][local_off + 65]);
                }
            }
            __syncthreads();
        }
    }
    if (row < S) {
        half* Orow = O + bh_off + (size_t)row * D;
        float inv_l = 1.0f / l_i;
        #pragma unroll
        for (int s = 0; s < NUM_STAGES; s++) {
            half2 out0 = __floats2half2_rn(acc[s][0] * inv_l, acc[s][1] * inv_l);
            half2 out1 = __floats2half2_rn(acc[s][2] * inv_l, acc[s][3] * inv_l);
            *reinterpret_cast<half2*>(Orow + s * D_TILE + local_off) = out0;
            *reinterpret_cast<half2*>(Orow + s * D_TILE + local_off + 64) = out1;
        }
    }
}
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.dtype() == torch::kFloat16 && K.dtype() == torch::kFloat16 && V.dtype() == torch::kFloat16,
                "Q, K, V must be fp16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Q, K, V must be contiguous");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have matching shapes");
    int B = Q.size(0);
    int H = Q.size(1);
    int S = Q.size(2);
    int Dh = Q.size(3);
    TORCH_CHECK(Dh == D, "This kernel is specialized for head_dim = 1024");
    auto O = torch::empty_like(Q);
    float scale = 1.0f / sqrtf((float)Dh);
    dim3 grid(B * H, (S + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK);
    dim3 block(WARPS_PER_BLOCK * 32);
    flash_attention_kernel<<<grid, block>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, scale);
    return O;
}
